        const zc = buildZeroCrossing(condition);
        return {
            condition,
            actions,
            wasActive: false,
            zeroCrossingFn: zc?.fn ?? null,
            zeroCrossingDirection: zc?.direction ?? "either",
            gPrev: 0,
        };
